local AbacusMaker = {}
local PRODUCTS = {
    wooden_abacus = { name = "Leseni abak", woodCost = 2, time = 2, cost = 15, precision = 40, description = "Leseni abak za računanje." },
    brass_abacus = { name = "Medeninast abak", woodCost = 1, brassCost = 1, time = 3, cost = 40, precision = 55, prestige = 1, description = "Medeninast abak za trgovce." },
    silver_abacus = { name = "Srebrn abak", woodCost = 1, silverCost = 1, brassCost = 1, time = 5, cost = 100, precision = 70, prestige = 4, happiness = 1, description = "Srebrn abak za bančnike." },
    silver_wire_abacus = { name = "Srebrnožični abak", silverCost = 2, woodCost = 1, time = 7, cost = 240, precision = 82, prestige = 8, happiness = 2, description = "Abak s srebrnimi žicami za plemiče." },
    gold_bead_abacus = { name = "Zlatokroglični abak", goldCost = 1, silverCost = 1, woodCost = 1, time = 10, cost = 560, precision = 92, prestige = 15, happiness = 3, description = "Abak z zlatimi kroglicami za visoke plemiče." },
    royal_grand_abacus = { name = "Kraljevski veliki abak", goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, woodCost = 1, time = 15, cost = 1600, precision = 100, prestige = 38, happiness = 8, description = "Veliki kraljevski abak z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Abakarska delavnica", cost = { gold = 240, wood = 130, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    bead_workshop = { name = "Krogličarna", cost = { gold = 800, wood = 220, stone = 350, brass = 6 }, upkeep = 20, qualityBonus = 18 },
    precision_room = { name = "Natančnostna soba", cost = { gold = 2100, wood = 350, stone = 600, silver = 25, steel = 8 }, upkeep = 52, qualityBonus = 30 },
    royal_abacus_atelier = { name = "Kraljevski atelje abakov", cost = { gold = 8500, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 170, qualityBonus = 55, prestigeBonus = 40 },
}
AbacusMaker.woodStock = 18; AbacusMaker.brassStock = 12; AbacusMaker.silverStock = 8; AbacusMaker.goldStock = 6; AbacusMaker.jewelStock = 6; AbacusMaker.pearlStock = 4
AbacusMaker.productStock = {}; AbacusMaker.buildings = {}; AbacusMaker.maker = nil; AbacusMaker.activeMaking = {}; AbacusMaker.totalProducts = 0; AbacusMaker.dayTimer = 0
function AbacusMaker.init() AbacusMaker.woodStock=18; AbacusMaker.brassStock=12; AbacusMaker.silverStock=8; AbacusMaker.goldStock=6; AbacusMaker.jewelStock=6; AbacusMaker.pearlStock=4; AbacusMaker.productStock={}; AbacusMaker.buildings={}; AbacusMaker.maker=nil; AbacusMaker.activeMaking={}; AbacusMaker.totalProducts=0; AbacusMaker.dayTimer=0; print("[AbacusMaker] Royal Abacus Maker System initialized (6 products, 4 buildings)") end
function AbacusMaker.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AbacusMaker.maker={name=n or ("Abakar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Abakar najet: %s (spretnost: %d)",AbacusMaker.maker.name,s),"success") end; return true end
function AbacusMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AbacusMaker.build(id) local ok,e=AbacusMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AbacusMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AbacusMaker.getQualityBonus() local b=0; for _,bd in ipairs(AbacusMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AbacusMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and AbacusMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.brassCost and AbacusMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and AbacusMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AbacusMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AbacusMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AbacusMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AbacusMaker.buildings==0 then return false,"Potrebna delavnica" end; if not AbacusMaker.maker then return false,"Potreben abakar" end; return true end
function AbacusMaker.make(pt,qty) qty=qty or 1; local ok,e=AbacusMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then AbacusMaker.woodStock=AbacusMaker.woodStock-d.woodCost*qty end; if d.brassCost then AbacusMaker.brassStock=AbacusMaker.brassStock-d.brassCost*qty end; if d.silverCost then AbacusMaker.silverStock=AbacusMaker.silverStock-d.silverCost*qty end; if d.goldCost then AbacusMaker.goldStock=AbacusMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AbacusMaker.jewelStock=AbacusMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AbacusMaker.pearlStock=AbacusMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AbacusMaker.maker then t=math.max(1,t-math.floor(AbacusMaker.maker.skill/12)) end; table.insert(AbacusMaker.activeMaking,{id="abacus_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,precision=d.precision or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AbacusMaker.completeMaking(m) local q=1.0+(AbacusMaker.getQualityBonus()/100); if AbacusMaker.maker then q=q+(AbacusMaker.maker.skill/180) end; q=math.min(2.0,q); AbacusMaker.productStock[m.productType]=(AbacusMaker.productStock[m.productType] or 0)+m.quantity; AbacusMaker.totalProducts=AbacusMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AbacusMaker.maker then AbacusMaker.maker.itemsMade=AbacusMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then AbacusMaker.maker.skill=math.min(100,AbacusMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Abak izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"abacus.completed",{productName=m.productName,precision=m.precision}) end end
function AbacusMaker.update(dt) if not _G.state then return end; AbacusMaker.dayTimer=AbacusMaker.dayTimer+dt; if AbacusMaker.dayTimer>=30 then AbacusMaker.dayTimer=0; for i=#AbacusMaker.activeMaking,1,-1 do local m=AbacusMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AbacusMaker.completeMaking(m); table.remove(AbacusMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AbacusMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AbacusMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AbacusMaker.getStats() return {woodStock=AbacusMaker.woodStock,brassStock=AbacusMaker.brassStock,silverStock=AbacusMaker.silverStock,goldStock=AbacusMaker.goldStock,jewelStock=AbacusMaker.jewelStock,pearlStock=AbacusMaker.pearlStock,productStock=AbacusMaker.productStock,numBuildings=#AbacusMaker.buildings,hasMaker=AbacusMaker.maker~=nil,makerName=AbacusMaker.maker and AbacusMaker.maker.name or "—",makerSkill=AbacusMaker.maker and AbacusMaker.maker.skill or 0,activeMaking=#AbacusMaker.activeMaking,totalProducts=AbacusMaker.totalProducts} end
return AbacusMaker
